// Offline Supabase – fully thenable, never missing .catch

function id() { return Date.now().toString(36)+Math.random().toString(36).substr(2); }
function get(t) { try{ return JSON.parse(localStorage.getItem('bwanali_'+t)||'[]'); }catch{ return []; } }
function set(t,r) { localStorage.setItem('bwanali_'+t,JSON.stringify(r)); }

// Seed once
if (!localStorage.getItem('bwanali_seeded')) {
  set('stores',[{id:'store-1',name:'Demo Store',subscription_status:'trialing',trial_started_at:new Date().toISOString(),subscription_plan:'monthly',locked:false}]);
  set('staff',[{id:'staff-1',store_id:'store-1',full_name:'Admin Demo',email:'admin@demo.com',role:'admin',pin_code:'1234',is_active:true}]);
  set('products',[{id:'prod-1',store_id:'store-1',name:'Cooking Oil 2L',barcode:'111',category:'Groceries',unit_price:230,cost_price:210,stock_quantity:20,is_active:true},{id:'prod-2',store_id:'store-1',name:'Sugar 1kg',barcode:'222',category:'Groceries',unit_price:38,cost_price:30,stock_quantity:100,is_active:true},{id:'prod-3',store_id:'store-1',name:'Bread Loaf',barcode:'333',category:'Bakery',unit_price:25,cost_price:18,stock_quantity:50,is_active:true}]);
  set('company_settings',[{id:'settings-1',store_id:'store-1',company_name:'Demo Store Ltd',local_currency:'ZMW',receipt_footer:'Thank you!'}]);
  set('customers',[]);set('sales',[]);set('sale_items',[]);set('cash_shifts',[]);set('discount_rules',[]);set('returns',[]);set('laybys',[]);
  localStorage.setItem('bwanali_seeded','1');
}

// --------- Promise-like wrapper ---------
function P(val) {
  const obj = {
    then: (fn) => { try { const r = fn(val); return P(r); } catch(e) { return P(e); } },
    catch: (fn) => { return P(val); },
  };
  // if val is already a thenable, just ensure catch exists
  if (val && typeof val.then === 'function') {
    if (!val.catch) val.catch = (fn) => val;
    return val;
  }
  return obj;
}

// --------- Query builder ---------
function builder(table) {
  let rows = get(table);
  let filters = [];
  let countMode = false, headOnly = false;

  const apply = () => {
    let list = [...rows];
    filters.forEach(f => {
      try {
        if (f.type==='eq') list = list.filter(r => r[f.col] === f.val);
        else if (f.type==='gte') list = list.filter(r => new Date(r[f.col]) >= new Date(f.val));
        else if (f.type==='lte') list = list.filter(r => new Date(r[f.col]) <= new Date(f.val));
        else if (f.type==='not') list = list.filter(r => r[f.col] !== f.val);
        else if (f.type==='is') list = list.filter(r => r[f.col] === null);
      } catch(e) {}
    });
    return list;
  };

  const chain = {
    eq: (col,val) => { filters.push({type:'eq',col,val}); return chain; },
    gte: (col,val) => { filters.push({type:'gte',col,val}); return chain; },
    lte: (col,val) => { filters.push({type:'lte',col,val}); return chain; },
    not: (col,val) => { filters.push({type:'not',col,val}); return chain; },
    is: (col,val) => { filters.push({type:'is',col,val}); return chain; },
    order: (col,opt) => {
      const list = apply();
      list.sort((a,b) => (a[col] > b[col] ? 1 : -1) * (opt?.ascending!==false ? 1 : -1));
      return P({ data: list, error: null });
    },
    single: () => { const list = apply(); return P({ data: list[0] || null, error: null }); },
    maybeSingle: () => { const list = apply(); return P({ data: list[0] || null, error: null }); },
    limit: (n) => {
      const list = apply();
      const result = countMode ? { count: headOnly ? list.length : apply().length, data: headOnly ? [] : list.slice(0,n) } : { data: list.slice(0,n), error: null };
      return P(result);
    },
    then: (fn) => {
      const list = apply();
      fn(countMode ? { count: list.length, data: list } : { data: list, error: null });
    },
    catch: () => chain,
  };

  return { chain, setCount: () => { countMode=true; }, setHead: () => { headOnly=true; } };
}

// --------- The fake supabase ---------
const fake = {
  from: (t) => {
    const b = builder(t);
    return P({
      select: (cols,opt) => {
        if (opt?.count==='exact') { b.setCount(); if (opt.head) b.setHead(); }
        return b.chain;
      },
      insert: (data) => {
        const arr = Array.isArray(data)?data:[data];
        const newRows = arr.map(d => ({ id:id(), ...d }));
        const cur = get(t);
        set(t, [...cur, ...newRows]);
        return P({ data: newRows, error: null });
      },
      update: (data) => P({
        eq: (col,val) => {
          const cur = get(t);
          set(t, cur.map(r => r[col]===val ? { ...r, ...data } : r));
          return P({ error: null });
        },
        in: (col,vals) => {
          const cur = get(t);
          set(t, cur.map(r => vals.includes(r[col]) ? { ...r, ...data } : r));
          return P({ error: null });
        },
      }),
      delete: () => P({
        eq: (col,val) => {
          const cur = get(t);
          set(t, cur.filter(r => r[col]!==val));
          return P({ error: null });
        },
      }),
      upsert: (data) => {
        const cur = get(t);
        (Array.isArray(data)?data:[data]).forEach(d => {
          const idx = cur.findIndex(r => r.id===d.id);
          if (idx>=0) cur[idx]=d; else cur.push({ id:id(), ...d });
        });
        set(t, cur);
        return P({ error: null });
      },
    });
  },
  auth: {
    signInWithPassword: async ({email,password}) => {
      const staff = get('staff');
      const user = staff.find(u => u.email===email && u.pin_code===password);
      if (!user) return { error:{message:'Invalid credentials'} };
      localStorage.setItem('local_user',JSON.stringify(user));
      return { data:{ user }, error: null };
    },
    signOut: async () => { localStorage.removeItem('local_user'); return { error:null }; },
    getSession: async () => {
      const raw = localStorage.getItem('local_user');
      const user = raw ? JSON.parse(raw) : null;
      return { data:{ session: user ? { user, access_token:'offline', refresh_token:'offline' } : null } };
    },
    onAuthStateChange: (cb) => {
      const user = JSON.parse(localStorage.getItem('local_user')||'null');
      setTimeout(() => cb('SIGNED_IN',{ user }), 10);
      return P({ data:{ subscription:{ unsubscribe:()=>{} } } });
    },
    setSession: async () => ({ error:null }),
    signUp: async ({email,password,options}) => {
      const staff = get('staff');
      const newUser = { id:id(), email, pin_code:password, full_name: options?.data?.full_name||'New User', role:'cashier', is_active:true, store_id:null };
      set('staff', [...staff, newUser]);
      return { data:{ user:newUser }, error:null };
    },
  },
  storage: {
    from: () => ({
      upload: async () => P({ error:null }),
      getPublicUrl: () => P({ data:{ publicUrl:'' } }),
    }),
  },
  rpc: () => P({ error:null }),
};

export const supabase = fake;
